import { BaseComponent } from '../base-component';

export default BaseComponent.extend({
    name: 'ImageAndText',
    props: {
        text: {
            type: String,
            required: true,
        },
        image: {
            type: String,
            required: true,
        },
        imagePercentage: {
            type: Number,
            default: 20,
        },
        imageFirst: {
            type: Boolean,
            default: true,
        },
    },
    computed: {
        imageStyle() {
            const width = this.imagePercentage + '%';
            return {
                width: width,
            };
        },
        textStyle() {
            const baseStyle = (BaseComponent as any).options.computed.textStyle.call(this);
            const extraStyle = {
                width: (100 - (this.imagePercentage as number)) + '%',
            };

            // Merge and return the combined styles
            return { ...baseStyle, ...extraStyle };
        },
    },
});